entry:
  entry_name: DIp
  slug: DIp_n
  part_of_speech: n:klcp1
  pos: n
  metadata_tags:
  - klcp1
  status: canonical
  section: main
  definition: noun
  see_also: '{wot:n}, {Dol DIp:n}, {ghom DIp:n}'
  notes: 'There are five types of noun suffixes in Klingon.


    Noun Type 1: Augmentative/diminutive

    ▶ {-''a'':n:suff}

    ▶ {-Hom:n:suff}

    ▶ {-oy:n:suff}


    Noun Type 2: Number

    ▶ {-pu'':n:suff}

    ▶ {-Du'':n:suff}

    ▶ {-mey:n:suff}


    Noun Type 3: Qualification

    ▶ {-qoq:n:suff}

    ▶ {-Hey:n:suff}

    ▶ {-na'':n:suff}


    Noun Type 4: Possession/specification

    ▶ {-wIj:n:suff} / {-wI'':n:suff}

    ▶ {-lIj:n:suff} / {-lI'':n:suff}

    ▶ {-Daj:n:suff}

    ▶ {-maj:n:suff} / {-ma'':n:suff}

    ▶ {-raj:n:suff} / {-ra'':n:suff}

    ▶ {-chaj:n:suff}

    ▶ {-vam:n:suff}

    ▶ {-vetlh:n:suff}


    Noun Type 5: Syntactic markers

    ▶ {-Daq:n:suff}

    ▶ {-vo'':n:suff}

    ▶ {-mo'':n:suff}

    ▶ {-vaD:n:suff}

    ▶ {-''e'':n:suff}'
  examples: '

    ▶ {QaghHommeyHeylIjmo'':n}'
  sources:
    raw: '[1] {TKD:src}'
    citations:
    - source: tkd
  translations:
    de:
      definition: Nomen, Substantiv
      notes: 'Es gibt fünf Arten von Nomensuffixen im Klingonischen.


        Nomen Typ 1: Augmentativ/Diminutiv

        ▶ {-''a'':n:suff}

        ▶ {-Hom:n:suff}

        ▶ {-oy:n:suff}


        Nomen Typ 2: Numerus

        ▶ {-pu'':n:suff}

        ▶ {-Du'':n:suff}

        ▶ {-mey:n:suff}


        Nomen Typ 3: Qualifizierung

        ▶ {-qoq:n:suff}

        ▶ {-Hey:n:suff}

        ▶ {-na'':n:suff}


        Nomen Typ 4: Besitz/Spezifizierung

        ▶ {-wIj:n:suff} / {-wI'':n:suff}

        ▶ {-lIj:n:suff} / {-lI'':n:suff}

        ▶ {-Daj:n:suff}

        ▶ {-maj:n:suff} / {-ma'':n:suff}

        ▶ {-raj:n:suff} / {-ra'':n:suff}

        ▶ {-chaj:n:suff}

        ▶ {-vam:n:suff}

        ▶ {-vetlh:n:suff}


        Nomen Typ 5: Syntaktische Marker

        ▶ {-Daq:n:suff}

        ▶ {-vo'':n:suff}

        ▶ {-mo'':n:suff}

        ▶ {-vaD:n:suff}

        ▶ {-''e'':n:suff}'
    fa:
      definition: اسم
    sv:
      definition: substantiv (grammatisk term)
    ru:
      definition: имя существительное
      notes: 'Есть пять типов суффиксов для имен существительных в Клингонском языке.


        Тип 1: Усиливающий/уменьшающий

        ▶ {-''a'':n:suff}

        ▶ {-Hom:n:suff}

        ▶ {-oy:n:suff}


        Тип 2: Числительные

        ▶ {-pu'':n:suff}

        ▶ {-Du'':n:suff}

        ▶ {-mey:n:suff}


        Тип 3: Квалифицирующие

        ▶ {-qoq:n:suff}

        ▶ {-Hey:n:suff}

        ▶ {-na'':n:suff}


        Тип 4: имущественные/определяющие

        ▶ {-wIj:n:suff} / {-wI'':n:suff}

        ▶ {-lIj:n:suff} / {-lI'':n:suff}

        ▶ {-Daj:n:suff}

        ▶ {-maj:n:suff} / {-ma'':n:suff}

        ▶ {-raj:n:suff} / {-ra'':n:suff}

        ▶ {-chaj:n:suff}

        ▶ {-vam:n:suff}

        ▶ {-vetlh:n:suff}


        Тип 5: Синтаксические маркеры

        ▶ {-Daq:n:suff}

        ▶ {-vo'':n:suff}

        ▶ {-mo'':n:suff}

        ▶ {-vaD:n:suff}

        ▶ {-''e'':n:suff}'
    zh_HK:
      definition: 名詞
    pt:
      definition: substantivo
    fi:
      definition: substantiivi
      notes: 'Klingonin kielessä on viisi erilaista substantiiviliitetyyppiä.


        Liitetyyppi 1: augmentatiivi/diminutiivi

        ▶ {-''a'':n:suff}

        ▶ {-Hom:n:suff}

        ▶ {-oy:n:suff}


        Liitetyyppi 2: luku

        ▶ {-pu'':n:suff}

        ▶ {-Du'':n:suff}

        ▶ {-mey:n:suff}


        Liitetyyppi 3: suhtautuminen

        ▶ {-qoq:n:suff}

        ▶ {-Hey:n:suff}

        ▶ {-na'':n:suff}


        Liitetyyppi 4: omistus-, demonstratiiviliitteet

        ▶ {-wIj:n:suff} / {-wI'':n:suff}

        ▶ {-lIj:n:suff} / {-lI'':n:suff}

        ▶ {-Daj:n:suff}

        ▶ {-maj:n:suff} / {-ma'':n:suff}

        ▶ {-raj:n:suff} / {-ra'':n:suff}

        ▶ {-chaj:n:suff}

        ▶ {-vam:n:suff}

        ▶ {-vetlh:n:suff}


        Liitetyyppi 5: sijamuodot

        ▶ {-Daq:n:suff}

        ▶ {-vo'':n:suff}

        ▶ {-mo'':n:suff}

        ▶ {-vaD:n:suff}

        ▶ {-''e'':n:suff}'
    fr:
      definition: nom

