entry:
  entry_name: wot
  slug: wot_n
  part_of_speech: n:klcp1
  pos: n
  metadata_tags:
  - klcp1
  status: canonical
  section: main
  definition: verb
  see_also: '{DIp:n}'
  notes: 'There are nine types of verb suffixes in Klingon, in addition to the rovers
    ({lengwI'':n}), which do not have a fixed position relative to the other suffix
    types.


    Verb Type 1: Oneself/one another

    ▶ {-''egh:v:suff}

    ▶ {-chuq:v:suff}


    Verb Type 2: Volition/predisposition

    ▶ {-nIS:v:suff}

    ▶ {-qang:v:suff}

    ▶ {-rup:v:suff}

    ▶ {-beH:v:suff}

    ▶ {-vIp:v:suff}


    Verb Type 3: Change

    ▶ {-choH:v:suff}

    ▶ {-qa'':v:suff}


    Verb Type 4: Cause

    ▶ {-moH:v:suff}


    Verb Type 5: Indefinite subject/ability

    ▶ {-lu'':v:suff}

    ▶ {-laH:v:suff}


    Verb Type 6: Qualification

    ▶ {-chu'':v:suff}

    ▶ {-bej:v:suff}

    ▶ {-law'':v:suff}

    ▶ {-ba'':v:suff}


    Verb Type 7: Aspect

    ▶ {-pu'':v:suff}

    ▶ {-ta'':v:suff}

    ▶ {-taH:v:suff}

    ▶ {-lI'':v:suff}


    Verb Type 8: Honorific

    ▶ {-neS:v:suff}


    Verb Type 9: Syntactic markers

    ▶ {-DI'':v:suff}

    ▶ {-chugh:v:suff}

    ▶ {-pa'':v:suff}

    ▶ {-vIS:v:suff}

    ▶ {-bogh:v:suff}

    ▶ {-meH:v:suff}

    ▶ {-''a'':v:suff}

    ▶ {-wI'':v:suff}

    ▶ {-mo'':v:suff}

    ▶ {-jaj:v:suff}

    ▶ {-ghach:v:suff}


    Rovers:

    ▶ {-be'':v:suff}

    ▶ {-Qo'':v:suff}

    ▶ {-Ha'':v:suff}

    ▶ {-qu'':v:suff}


    See under {moHaq:n} for the verb prefixes.'
  examples: '

    ▶ {bIQong''eghqangchoHmoHlaHchu''pu''neSchugh:v}'
  sources:
    raw: '[1] {TKD:src}'
    citations:
    - source: tkd
  translations:
    de:
      definition: Verb
      notes: 'Es gibt neuen Arten von Verbsuffixen im Klingonischen, plus die Rover
        ({lengwI'':n}), die keine feste Position bezüglich den anderen Suffixklassen
        haben.


        Verbsuffix Typ 1: Sich selbst/einander

        ▶ {-''egh:v:suff}

        ▶ {-chuq:v:suff}


        Verbsuffix Typ 2: Bereitschaft/Neigung

        ▶ {-nIS:v:suff}

        ▶ {-qang:v:suff}

        ▶ {-rup:v:suff}

        ▶ {-beH:v:suff}

        ▶ {-vIp:v:suff}


        Verbsuffix Typ 3: Veränderung

        ▶ {-choH:v:suff}

        ▶ {-qa'':v:suff}


        Verbsuffix Typ 4: Kausatif

        ▶ {-moH:v:suff}


        Versuffix Typ 5: Indefinites Subjekt/Fähigkeit

        ▶ {-lu'':v:suff}

        ▶ {-laH:v:suff}


        Verbsuffix Typ 6: Qualifikation

        ▶ {-chu'':v:suff}

        ▶ {-bej:v:suff}

        ▶ {-law'':v:suff}

        ▶ {-ba'':v:suff}


        Verbsuffix Typ 7: Aspekt

        ▶ {-pu'':v:suff}

        ▶ {-ta'':v:suff}

        ▶ {-taH:v:suff}

        ▶ {-lI'':v:suff}


        Verbsuffix Typ 8: Ehrerbietung

        ▶ {-neS:v:suff}


        Verbsuffix Typ 9: Syntaxmarker

        ▶ {-DI'':v:suff}

        ▶ {-chugh:v:suff}

        ▶ {-pa'':v:suff}

        ▶ {-vIS:v:suff}

        ▶ {-bogh:v:suff}

        ▶ {-meH:v:suff}

        ▶ {-''a'':v:suff}

        ▶ {-wI'':v:suff}

        ▶ {-mo'':v:suff}

        ▶ {-jaj:v:suff}

        ▶ {-ghach:v:suff}


        Rover:

        ▶ {-be'':v:suff}

        ▶ {-Qo'':v:suff}

        ▶ {-Ha'':v:suff}

        ▶ {-qu'':v:suff}


        Siehe {moHaq:n} für die Verbpräfixe.'
    fa:
      definition: فعل
    sv:
      definition: verb
    ru:
      definition: глагол
    zh_HK:
      definition: 動詞
    pt:
      definition: verbo
    fi:
      definition: verbi
      notes: 'Klingonissa on yhdeksän verbipäätetyyppiä, joita on aina käytettävä
        oikeassa järjestyksessä. Lisäksi on ns. seikkailijoita ({lengwI'':n}), joilla
        ei ole omaa paikkaa järjestyksessä.


        Päätetyyppi 1: itseään/toisiaan

        ▶ {-''egh:v:suff}

        ▶ {-chuq:v:suff}


        Päätetyyppi 2: tahtominen/valmius

        ▶ {-nIS:v:suff}

        ▶ {-qang:v:suff}

        ▶ {-rup:v:suff}

        ▶ {-beH:v:suff}

        ▶ {-vIp:v:suff}


        Päätetyyppi 3: muutos

        ▶ {-choH:v:suff}

        ▶ {-qa'':v:suff}


        Päätetyyppi 4: aiheuttaminen

        ▶ {-moH:v:suff}


        Päätetyyppi 5: passiivi/kykeneminen

        ▶ {-lu'':v:suff}

        ▶ {-laH:v:suff}


        Päätetyyppi 6: suhtautuminen

        ▶ {-chu'':v:suff}

        ▶ {-bej:v:suff}

        ▶ {-law'':v:suff}

        ▶ {-ba'':v:suff}


        Päätetyyppi 7: aspekti

        ▶ {-pu'':v:suff}

        ▶ {-ta'':v:suff}

        ▶ {-taH:v:suff}

        ▶ {-lI'':v:suff}


        Päätetyyppi 8: kunnioituspääte

        ▶ {-neS:v:suff}


        Päätetyyppi 9: kieliopilliset päätteet

        ▶ {-DI'':v:suff}

        ▶ {-chugh:v:suff}

        ▶ {-pa'':v:suff}

        ▶ {-vIS:v:suff}

        ▶ {-bogh:v:suff}

        ▶ {-meH:v:suff}

        ▶ {-''a'':v:suff}

        ▶ {-wI'':v:suff}

        ▶ {-mo'':v:suff}

        ▶ {-jaj:v:suff}

        ▶ {-ghach:v:suff}


        Seikkailijat:

        ▶ {-be'':v:suff}

        ▶ {-Qo'':v:suff}

        ▶ {-Ha'':v:suff}

        ▶ {-qu'':v:suff}


        Katso verbietuliitteet artikkelissa {moHaq:n}.'
    fr:
      definition: verbe
      notes: 'Il y a neuf types de suffixes verbaux en klingon, en plus des vagabonds
        ({lengwI'':n}), qui n''ont pas de position fixe par rapport aux autres types
        de suffixes.


        Suffixes verbaux type 1: Soi-même/l''un-l''autre

        ▶ {-''egh:v:suff}

        ▶ {-chuq:v:suff}


        Suffixes verbaux type 2: Volition/prédisposition

        ▶ {-nIS:v:suff}

        ▶ {-qang:v:suff}

        ▶ {-rup:v:suff}

        ▶ {-beH:v:suff}

        ▶ {-vIp:v:suff}


        Suffixes verbaux type 3: Changement

        ▶ {-choH:v:suff}

        ▶ {-qa'':v:suff}


        Suffixes verbaux type 4: Cause

        ▶ {-moH:v:suff}


        Suffixes verbaux type 5: Sujet indéfini/capacité

        ▶ {-lu'':v:suff}

        ▶ {-laH:v:suff}


        Suffixes verbaux type 6: Qualification

        ▶ {-chu'':v:suff}

        ▶ {-bej:v:suff}

        ▶ {-law'':v:suff}

        ▶ {-ba'':v:suff}


        Suffixes verbaux type 7: Aspect

        ▶ {-pu'':v:suff}

        ▶ {-ta'':v:suff}

        ▶ {-taH:v:suff}

        ▶ {-lI'':v:suff}


        Suffixes verbaux type 8: Honorifique

        ▶ {-neS:v:suff}


        Suffixes verbaux type 9: Marqueurs syntaxiques

        ▶ {-DI'':v:suff}

        ▶ {-chugh:v:suff}

        ▶ {-pa'':v:suff}

        ▶ {-vIS:v:suff}

        ▶ {-bogh:v:suff}

        ▶ {-meH:v:suff}

        ▶ {-''a'':v:suff}

        ▶ {-wI'':v:suff}

        ▶ {-mo'':v:suff}

        ▶ {-jaj:v:suff}

        ▶ {-ghach:v:suff}


        Rovers:

        ▶ {-be'':v:suff}

        ▶ {-Qo'':v:suff}

        ▶ {-Ha'':v:suff}

        ▶ {-qu'':v:suff}


        Voir {moHaq:n} pour les préfixes verbaux.'
